<?php $categories=array_column(records('blog_categories'),'title');$selected=is_string($_GET['category']??null)&&in_array($_GET['category'],$categories)?$_GET['category']:'All';$posts=records('posts');$visibleCount=count(array_filter($posts,fn($p)=>$selected==='All'||$p['category']===$selected));?>
<div class="container"><header class="page-heading"><span class="eyebrow">INSIGHTS & FIELD NOTES</span><h1>Better questions.<br><span class="muted-heading">Better software decisions.</span></h1><p>Practical thinking on custom software, SaaS and the systems that help a business work better.</p></header><section class="listing-section" aria-label="Articles"><form class="filters" method="get" data-filter-form><?php foreach(array_merge(['All'],$categories) as $cat):?><button class="filter <?=$selected===$cat?'selected':''?>" type="submit" name="category" value="<?=e($cat)?>" data-filter="<?=e($cat)?>" aria-pressed="<?=$selected===$cat?'true':'false'?>"><?=e($cat)?></button><?php endforeach;?></form><p class="result-status" data-filter-status aria-live="polite"><?=$visibleCount?$visibleCount.' articles':'No articles in this category yet. Explore another category.'?></p><div class="blog-grid"><?php foreach($posts as $post)require __DIR__.'/../partials/blog-card.php';?></div></section></div><?php cta('Ready to put an idea<br>into practice?');?>
